<?php
/** Native XLSX download: all text uses inline strings, never executable formulas. */
function report_write_xlsx($path,$title,$headers,$rows,$metadata=[],$editable=[]){
 $x=fn($v)=>htmlspecialchars((string)$v,ENT_XML1|ENT_QUOTES,'UTF-8');
 $cell=function($col,$row,$value,$style=0)use($x){$ref=XlsxReader::colLetters($col).$row;if(is_int($value)||is_float($value))return '<c r="'.$ref.'" s="'.$style.'"><v>'.$value.'</v></c>';return '<c r="'.$ref.'" s="'.$style.'" t="inlineStr"><is><t xml:space="preserve">'.$x($value).'</t></is></c>';};
 $all=[[$title]];foreach($metadata as $k=>$v)$all[]=[$k,is_array($v)?json_encode($v):$v];$all[]=$headers;$hr=count($all);foreach($rows as $r)$all[]=array_values($r);$last=XlsxReader::colLetters(max(0,count($headers)-1));
 $xml='<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetPr><pageSetUpPr fitToPage="1"/></sheetPr><sheetViews><sheetView workbookViewId="0"><pane ySplit="'.$hr.'" topLeftCell="A'.($hr+1).'" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols>';
 foreach($headers as $i=>$h)$xml.='<col min="'.($i+1).'" max="'.($i+1).'" width="'.(preg_match('/product|description|remarks|reason|details/i',$h)?50:23).'" customWidth="1"/>';$xml.='</cols><sheetData>';
 foreach($all as $ri=>$r){$n=$ri+1;$xml.='<row r="'.$n.'">';foreach($r as $i=>$v)$xml.=$cell($i,$n,$v,$n===1||$n===$hr?1:($n>$hr&&in_array($i,$editable,true)?3:2));$xml.='</row>';}
 $xml.='</sheetData><autoFilter ref="A'.$hr.':'.$last.count($all).'"/><printOptions horizontalCentered="1"/><pageMargins left="0.25" right="0.25" top="0.5" bottom="0.5" header="0.2" footer="0.2"/><pageSetup paperSize="9" orientation="landscape" fitToWidth="1" fitToHeight="0"/><headerFooter><oddFooter>&amp;CPage &amp;P of &amp;N</oddFooter></headerFooter></worksheet>';
 $z=new ZipArchive();if($z->open($path,ZipArchive::CREATE|ZipArchive::OVERWRITE)!==true)throw new Exception('Cannot create workbook.');
 $z->addFromString('[Content_Types].xml','<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>');
 $z->addFromString('_rels/.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');
 $z->addFromString('xl/workbook.xml','<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Report" sheetId="1" r:id="rId1"/></sheets><definedNames><definedName name="_xlnm.Print_Titles" localSheetId="0">\'Report\'!$1:$'.$hr.'</definedName></definedNames></workbook>');
 $z->addFromString('xl/_rels/workbook.xml.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>');
 $z->addFromString('xl/styles.xml','<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="2"><font><sz val="11"/><name val="Arial"/></font><font><b/><sz val="11"/><name val="Arial"/><color rgb="FFFFFFFF"/></font></fonts><fills count="4"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF16263C"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FFFFF2CC"/></patternFill></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf/></cellStyleXfs><cellXfs count="4"><xf fontId="0" fillId="0" borderId="0" xfId="0"/><xf fontId="1" fillId="2" borderId="0" xfId="0" applyFont="1" applyFill="1"><alignment wrapText="1"/></xf><xf fontId="0" fillId="0" borderId="0" xfId="0"><alignment wrapText="1" vertical="top"/></xf><xf fontId="0" fillId="3" borderId="0" xfId="0" applyFill="1"><alignment wrapText="1" vertical="top"/></xf></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>');
 $z->addFromString('xl/worksheets/sheet1.xml',$xml);if(!$z->close())throw new Exception('Workbook could not be saved.');
}
function report_print_document($title,$headers,$rows,$meta=[]){
 echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><title>'.e($title).'</title><style>body{font:12px Arial,sans-serif;color:#16263c;margin:24px}h1{font-size:22px}table{width:100%;border-collapse:collapse}th,td{padding:8px;border-bottom:1px solid #cfd8e3;text-align:left;overflow-wrap:anywhere}th{background:#edf2f7}thead{display:table-header-group}tr{break-inside:avoid}.meta{margin:12px 0;line-height:1.6}.foot{margin-top:14px;color:#53647a}@page{size:A4 landscape;margin:12mm}@media print{button{display:none}}</style><link rel="stylesheet" href="assets/typography.css?v=5.4.6-b"></head><body><button onclick="window.print()">Print / Save as PDF</button><h1>'.e($title).'</h1><b>E-commerce Inventory Management System</b><div class="meta">';foreach($meta as $k=>$v)echo e($k).': '.e(is_array($v)?json_encode($v):$v).'<br>';echo '</div><table><thead><tr>';foreach($headers as $h)echo '<th>'.e($h).'</th>';echo '</tr></thead><tbody>';foreach($rows as $r){echo '<tr>';foreach($r as $v)echo '<td>'.e($v).'</td>';echo '</tr>';}if(!$rows)echo '<tr><td colspan="'.count($headers).'">No matching records.</td></tr>';echo '</tbody></table><p class="foot">Read-only report. Quantities in pieces. Use browser print settings for page numbers.</p></body></html>';
}
